code.cpp:
class Solution {
public:
    bool splitArraySameAverage(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return false;

        int S = 0;
        for (int x : nums) S += x;

        vector<bitset<300001>> dp(n + 1);
        dp[0][0] = 1;

        for (int x : nums) {
            for (int k = n; k >= 1; --k) {
                dp[k] |= dp[k - 1] << x;
            }
        }

        for (int k = 1; k < n; ++k) {
            if ((S * k) % n == 0) {
                int target = (S * k) / n;
                if (dp[k][target]) {
                    return true;
                }
            }
        }

        return false;
    }
};
